def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    v3 = vars["v3"]
    value = (v1 + v2 + v3) / 3
    return {
        "value": value,
        "trace": {
            "v1": v1,
            "v2": v2,
            "v3": v3,
            "count": 3,
            "sum": v1 + v2 + v3,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
